mapper.update:
update DIS_PROD_PLAN
set
    DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
    where PROD_PLAN_ID = #{prodPlanId,jdbcType=VARCHAR}

mapper.select:
select *
from DIS_PROD_PLAN
where PROD_ID = #{prodId,jdbcType=VARCHAR}
and OPERATION_START_DATE = #{operationStartDate,jdbcType=DATE}

    and PROD_PLAN_ID != #{prodPlanId,jdbcType=VARCHAR}

select *
from V_REP_PROD_INFO
where PROD_ID = #{prodId,jdbcType=VARCHAR}

    and status = #{status,jdbcType=VARCHAR}
